import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const b=JSON.parse('{"title":"Blues","description":"","frontmatter":{},"headers":[],"relativePath":"demos/BLUES.md","filePath":"demos/BLUES.md"}'),s={name:"demos/BLUES.md"};function l(n,e,h,d,i,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="blues" tabindex="-1">Blues <a class="header-anchor" href="#blues" aria-label="Permalink to &quot;Blues&quot;">​</a></h1><p>The demo songs in the blues style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#blues_chords">Twelve-Bar Blues</a>: <code>07_blues_chords.yml</code></li><li><a href="#groove">Grooves</a>: <code>09_groove.yml</code></li></ul><p><a id="blues_chords"></a></p><h2 id="twelve-bar-blues-07-blues-chords-yml" tabindex="-1">Twelve-Bar Blues: <code>07_blues_chords.yml</code> <a class="header-anchor" href="#twelve-bar-blues-07-blues-chords-yml" aria-label="Permalink to &quot;Twelve-Bar Blues: `07_blues_chords.yml`&quot;">​</a></h2><p>A shuffle blues in G, where the walking bass, the comping chords and the riff are each one bar long, played through the twelve-bar blues and the quick-change blues. The comp&#39;s chord is a dominant seventh, which stays one on every chord of the blues, and the riff&#39;s blue note moves with the chords.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/07_blues_chords.yml" target="_blank" rel="noreferrer"><code>examples/learning/07_blues_chords.yml</code></a> · G major · 96 BPM · 3:00 · 6 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">grooves</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="groove"></a></p><h2 id="grooves-09-groove-yml" tabindex="-1">Grooves: <code>09_groove.yml</code> <a class="header-anchor" href="#grooves-09-groove-yml" aria-label="Permalink to &quot;Grooves: `09_groove.yml`&quot;">​</a></h2><p>A twelve-bar organ shuffle in G minor, llamatron&#39;s own tune in the spirit of a sixties organ trio: a Hammond lick, walking pedals, seventh chords bubbling through an arpeggiator, and drums. The song shuffles with the factory groove <code>8th swing 66</code>, the pedals and pads keep grooves of their own, the drums are <code>off</code> so the kick and snare stay on the grid, and the scenes play it straight, drag it behind the beat with a groove of the set&#39;s own, and shuffle it harder, so you can hear how the track&#39;s choice wins over the scene&#39;s, which wins over the song&#39;s.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/09_groove.yml" target="_blank" rel="noreferrer"><code>examples/learning/09_groove.yml</code></a> · G minor · 130 BPM · 1:51 · 5 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">grooves</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',13)])])}const m=t(s,[["render",l]]);export{b as __pageData,m as default};
